{"version":3,"sources":["..\\scss\\profile_dialogs.scss","profile_dialogs.css","..\\scss\\_variables.scss","..\\scss\\_mixins.scss"],"names":[],"mappings":"AAGA;EACE,6BAAA;ACFF;;ADOA;EACE,gBAAA;EACA,iBAAA;EACA,iBAAA;EACA,QAAA;EACA,aAAA;EACA,sBAAA;ACJF;;ADOA;EACE,qBAAA;EACA,gCAAA;ACJF;;ADOA;EACE,aAAA;EACA,mBAAA;EACA,kBAAA;EACA,SAAA;ACJF;ADME;EACE,YE7BW;ADyBf;;ADQA;EACE,eAAA;EACA,eAAA;ACLF;ADME;EACE,WAAA;EACA,YAAA;EACA,gBAAA;EACA,sBAAA;KAAA,mBAAA;ACJJ;;ADSA;EACE,eAAA;EACA,aAAA;EACA,sBAAA;EACA,SAAA;ACNF;;ADSA;EGpDI,uCAAA;EACA,gBHoDkC;EGnDlC,kBAAA;EACA,YDHW;ECIX,eHiD4B;EAC9B,gBAAA;EACA,oBAAA;EACA,qBAAA;EACA,4BAAA;ACFF;;ADKA;EG5DI,uCAAA;EACA,gBH4D4B;EG3D5B,kBAAA;EACA,cH0Da;EGzDb,eHyDsB;ACE1B;;ADCA;EACE,WAAA;EACA,YAAA;EACA,kBAAA;EACA,QAAA;EACA,UAAA;EACA,eAAA;ACEF;;ADCA;EACE,yBAAA;EACA,kBAAA;ACEF","file":"profile_dialogs.css","sourcesContent":["@import \"./variables\";\r\n@import \"./mixins\";\r\n\r\n.main__info {\r\n  border-top: 1px solid $gray;\r\n}\r\n\r\n\r\n\r\n.chat__list {\r\n  overflow-y: auto;\r\n  max-height: 550px;\r\n  padding-top: 10px;\r\n  gap: 5px;\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.chat__list-item-wrap {\r\n  padding: 5px 0 10px 0;\r\n  border-bottom: 1px solid $gray;\r\n}\r\n\r\n.chat__list-item {\r\n  display: flex;\r\n  align-items: center;\r\n  position: relative;\r\n  gap: 20px;\r\n\r\n  &:hover {\r\n    color: $defaultColor;\r\n  }\r\n}\r\n\r\n.chat__list-img {\r\n  padding: 10px 0;\r\n  flex: 0 0 120px;\r\n  & img {\r\n    width: 100%;\r\n    height: 100%;\r\n    max-height: 80px;\r\n    object-fit: contain;\r\n\r\n  }\r\n}\r\n\r\n.chat__list-text {\r\n  padding: 10px 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px\r\n}\r\n\r\n.chat__list-text-title {\r\n  @include fonts($defaultColor, 20px, 400);\r\n  overflow: hidden;\r\n  display: -webkit-box;\r\n  -webkit-line-clamp: 1;\r\n  -webkit-box-orient: vertical;\r\n}\r\n\r\n.chat__list-text-last-message {\r\n  @include fonts(#A9A9A9, 16px, 400);\r\n}\r\n\r\n.cross__dialog {\r\n  width: 20px;\r\n  height: 20px;\r\n  position: absolute;\r\n  top: 5px;\r\n  right: 5px;\r\n  cursor: pointer;\r\n}\r\n\r\n.unread {\r\n  background-color: #F0F8FF;\r\n  border-radius: 7px;\r\n}\r\n",".main__info {\n  border-top: 1px solid #D4D4D4;\n}\n\n.chat__list {\n  overflow-y: auto;\n  max-height: 550px;\n  padding-top: 10px;\n  gap: 5px;\n  display: flex;\n  flex-direction: column;\n}\n\n.chat__list-item-wrap {\n  padding: 5px 0 10px 0;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.chat__list-item {\n  display: flex;\n  align-items: center;\n  position: relative;\n  gap: 20px;\n}\n.chat__list-item:hover {\n  color: black;\n}\n\n.chat__list-img {\n  padding: 10px 0;\n  flex: 0 0 120px;\n}\n.chat__list-img img {\n  width: 100%;\n  height: 100%;\n  max-height: 80px;\n  object-fit: contain;\n}\n\n.chat__list-text {\n  padding: 10px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.chat__list-text-title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 20px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n\n.chat__list-text-last-message {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #A9A9A9;\n  font-size: 16px;\n}\n\n.cross__dialog {\n  width: 20px;\n  height: 20px;\n  position: absolute;\n  top: 5px;\n  right: 5px;\n  cursor: pointer;\n}\n\n.unread {\n  background-color: #F0F8FF;\n  border-radius: 7px;\n}","$mainColor: #3077a0;\r\n$defaultColor: black;\r\n$colorHover: red;\r\n$headerTopBorder: #bdd4e2;\r\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\r\n$gray: #D4D4D4;\r\n$vipBg: #ff6163;\r\n$activeItem: #FFFFCA;\r\n$userSearchBg: #CFE6FE;\r\n$asideLinksColor: #307792;\r\n$asideExitColor: rgb(0, 128, 0);","@mixin fonts($color,$size,$weight) {\r\n    font-family: 'Trebuchet MS', sans-serif;\r\n    font-weight: $weight;\r\n    font-style: normal;\r\n    color: $color;\r\n    font-size: $size;\r\n}"]}\r\n}"]}